BEGIN; DO $$ BEGIN IF to_regprocedure('public.is_admin()') IS NULL OR to_regclass('public.products') IS NULL THEN RAISE EXCEPTION 'Thiếu bảng mã hàng hoặc hàm kiểm tra Admin. Dừng cài đặt.'; END IF; END $$; CREATE OR REPLACE FUNCTION public.products_guard_deletion_v1() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE v_fk record; v_used boolean; BEGIN IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Không được xóa vĩnh viễn mã hàng. Hãy xóa mềm mã chưa dùng hoặc tắt Active để ngưng dùng.' USING ERRCODE='23503'; END IF; IF NEW.deleted_at IS NOT NULL AND OLD.deleted_at IS NULL THEN IF auth.uid() IS NULL OR public.is_admin() IS NOT TRUE THEN RAISE EXCEPTION 'Chỉ Admin hoặc Super Admin được xóa mã hàng.' USING ERRCODE='42501'; END IF; FOR v_fk IN SELECT DISTINCT n.nspname AS schema_name,c.relname AS table_name,a.attname AS column_name FROM pg_constraint co JOIN pg_class c ON c.oid=co.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL unnest(co.conkey,co.confkey) AS k(local_attnum,foreign_attnum) JOIN pg_attribute a ON a.attrelid=co.conrelid AND a.attnum=k.local_attnum JOIN pg_attribute pa ON pa.attrelid=co.confrelid AND pa.attnum=k.foreign_attnum WHERE co.contype='f' AND co.confrelid='public.products'::regclass AND pa.attname='id' ORDER BY 1,2,3 LOOP EXECUTE format('SELECT EXISTS(SELECT 1 FROM %I.%I r WHERE r.%I=$1)',v_fk.schema_name,v_fk.table_name,v_fk.column_name) INTO v_used USING OLD.id; IF v_used THEN RAISE EXCEPTION 'Mã hàng "%" đã được sử dụng (%). Không thể xóa vì có thể làm thiếu số liệu cũ. Chọn Sửa và tắt Active để ngưng dùng; lịch sử vẫn giữ nguyên.',OLD.sku,v_fk.table_name USING ERRCODE='23503'; END IF; END LOOP; NEW.deleted_by:=auth.uid(); END IF; RETURN NEW; END $$; DROP TRIGGER IF EXISTS trg_products_guard_deletion_v1 ON public.products; CREATE TRIGGER trg_products_guard_deletion_v1 BEFORE UPDATE OF deleted_at OR DELETE ON public.products FOR EACH ROW EXECUTE FUNCTION public.products_guard_deletion_v1(); CREATE OR REPLACE FUNCTION public.admin_soft_delete_products_v1(p_product_ids uuid[]) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE v_actor uuid:=auth.uid(); v_ids uuid[]; v_requested integer; v_locked integer; v_updated integer; BEGIN IF v_actor IS NULL OR public.is_admin() IS NOT TRUE THEN RAISE EXCEPTION 'Chỉ Admin hoặc Super Admin được xóa mã hàng.' USING ERRCODE='42501'; END IF; IF p_product_ids IS NULL OR cardinality(p_product_ids) NOT BETWEEN 1 AND 100 OR array_position(p_product_ids,NULL) IS NOT NULL THEN RAISE EXCEPTION 'Chọn từ 1 đến 100 mã hàng cần xóa.'; END IF; SELECT array_agg(DISTINCT x ORDER BY x) INTO v_ids FROM unnest(p_product_ids) x; v_requested:=cardinality(p_product_ids); IF cardinality(v_ids)<>v_requested THEN RAISE EXCEPTION 'Danh sách mã hàng bị trùng. Không mã nào thay đổi.'; END IF; PERFORM p.id FROM public.products p WHERE p.id=ANY(v_ids) ORDER BY p.id FOR UPDATE; GET DIAGNOSTICS v_locked=ROW_COUNT; IF v_locked<>v_requested OR EXISTS(SELECT 1 FROM public.products p WHERE p.id=ANY(v_ids) AND p.deleted_at IS NOT NULL) THEN RAISE EXCEPTION 'Có mã hàng không tồn tại hoặc đã xóa. Tải lại danh sách; không mã nào thay đổi.'; END IF; UPDATE public.products SET deleted_at=now(),deleted_by=v_actor,is_active=false WHERE id=ANY(v_ids) AND deleted_at IS NULL; GET DIAGNOSTICS v_updated=ROW_COUNT; IF v_updated<>v_requested THEN RAISE EXCEPTION 'Không xóa đủ mã hàng. Toàn bộ thao tác đã được hoàn tác.'; END IF; RETURN jsonb_build_object('success',true,'deleted_count',v_updated); END $$; REVOKE ALL ON FUNCTION public.products_guard_deletion_v1(),public.admin_soft_delete_products_v1(uuid[]) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.admin_soft_delete_products_v1(uuid[]) TO authenticated; NOTIFY pgrst,'reload schema'; COMMIT;
